// Generated by `just generate` from `src/plugins/claudetto/slices/worktree/domain/worktree.ts`. Edit the source and run `just generate`.
// The pure rules of the worktree hooks: the name, the path, and the files that a session made.

/** The folder of the agent worktrees, relative to the repository root. This is the folder that Claude Code uses. */
export const WORKTREE_DIR = ".claude/worktrees";

/** The file that names the ignored files to copy into a new worktree. */
export const INCLUDE_FILE = ".worktreeinclude";

/** The prefix of the branch of a worktree. */
export const BRANCH_PREFIX = "worktree-";

/** The hook input of `WorktreeCreate` and `WorktreeRemove`. The fields that the hooks do not read are left out. */
export type WorktreePayload = {
  name?: string;
  session_id?: string;
  cwd?: string;
  worktree_path?: string;
};

/** The parsed hook input, or `null` when the text is not a JSON object. */
export const parsePayload = (text: string): WorktreePayload | null => {
  try {
    const value: unknown = JSON.parse(text);
    return typeof value === "object" && value !== null && !Array.isArray(value)
      ? (value as WorktreePayload)
      : null;
  } catch {
    return null;
  }
};

/** True when `name` is one safe path part: letters, digits, `.`, `_`, and `-`, with no dot at the start. */
export const validName = (name: unknown): name is string =>
  typeof name === "string" && /^[A-Za-z0-9_][A-Za-z0-9._-]*$/.test(name);

/** The branch of the worktree `name`. */
export const branchOf = (name: string): string => `${BRANCH_PREFIX}${name}`;

/** The NUL-separated entries of a list, without the empty ones. */
export const entries = (text: string): string[] =>
  text.split("\0").filter((e) => e !== "");

/** True when a relative path stays inside the worktree. */
export const inside = (rel: string): boolean =>
  !rel.startsWith("/") && !rel.split("/").includes("..");

/**
 * The files of a session in the output of `git status --porcelain=v1 -z --ignored -uall`.
 * A path in `copied` came from `.worktreeinclude` and is ignored, so it does not count.
 * A rename entry has a second path, and that path is skipped.
 */
export const sessionFiles = (
  status: string,
  copied: ReadonlySet<string>,
): string[] => {
  const parts = entries(status);
  const files: string[] = [];
  for (let i = 0; i < parts.length; i++) {
    const entry = parts[i] as string;
    const code = entry.slice(0, 2);
    const file = entry.slice(3);
    if (code[0] === "R" || code[0] === "C") i++;
    if (code === "!!" && copied.has(file)) continue;
    files.push(file);
  }
  return files;
};
